import $ from 'jquery';

// Gắn jQuery vào window để các plugin khác dùng
if (typeof window !== 'undefined') {
  window.jQuery = window.$ = $;

  $(function () {
    // Sidebar type theo kích thước màn hình
    const setsidebartype = function () {
      const width = window.innerWidth || screen.width;
      if (width < 1199) {
        $("#main-wrapper").attr("data-sidebartype", "mini-sidebar").addClass("mini-sidebar");
      } else {
        $("#main-wrapper").attr("data-sidebartype", "full").removeClass("mini-sidebar");
      }
    };

    $(window).ready(setsidebartype);
    $(window).on("resize", setsidebartype);

    // Toggle sidebar
    $(".sidebartoggler").on("click", function () {
      $("#main-wrapper").toggleClass("mini-sidebar show-sidebar");
      const isMini = $("#main-wrapper").hasClass("mini-sidebar");
      $(".sidebartoggler").prop("checked", isMini);
      $("#main-wrapper").attr("data-sidebartype", isMini ? "mini-sidebar" : "full");
    });
  });
}
